77	    void CaresPTRResolver::resolve(const std::string & ip, std::vector<std::string> & response)
78	    {
79	        in_addr addr;
80	
81	        inet_pton(AF_INET, ip.c_str(), &addr);
82	
83	        ares_gethostbyaddr(channel, reinterpret_cast<const void*>(&addr), sizeof(addr), AF_INET, callback, &response);
84	    }
85	
86	    void CaresPTRResolver::resolve_v6(const std::string & ip, std::vector<std::string> & response)
87	    {
88	        in6_addr addr;
89	        inet_pton(AF_INET6, ip.c_str(), &addr);
90	
91	        ares_gethostbyaddr(channel, reinterpret_cast<const void*>(&addr), sizeof(addr), AF_INET6, callback, &response);
92	    }
