46	int mainImpl(int argc, char ** argv)
47	{
48	    using namespace DB;
49	
50	    const char * file_name = nullptr;
51	    Mode mode = MODE_READ;
52	    UInt64 min_offset = 0;
53	    UInt64 max_offset = 0;
54	    UInt64 block_size = 0;
55	    UInt64 descriptors = 0;
56	    UInt64 count = 0;
57	
58	    if (argc != 8)
59	    {
60	        std::cerr << "Usage: " << argv[0] << " file_name r|w min_offset max_offset block_size descriptors count" << std::endl;
61	        return 1;
62	    }
63	
64	    file_name = argv[1];
65	    min_offset = parse<UInt64>(argv[3]);
66	    max_offset = parse<UInt64>(argv[4]);
67	    block_size = parse<UInt64>(argv[5]);
68	    descriptors = parse<UInt64>(argv[6]);
69	    count = parse<UInt64>(argv[7]);
70	
71	    if (!strcmp(argv[2], "r"))
72	        mode = MODE_READ;
73	    else if (!strcmp(argv[2], "w"))
74	        mode = MODE_WRITE;
75	    else
76	        throw Poco::Exception("Invalid mode");
77	
78	    std::vector<int> fds(descriptors);
79	    for (size_t i = 0; i < descriptors; ++i)
80	    {
81	        fds[i] = open(file_name, O_SYNC | ((mode == MODE_READ) ? O_RDONLY : O_WRONLY));
82	        if (-1 == fds[i])
83	            throwFromErrno("Cannot open file", ErrorCodes::CANNOT_OPEN_FILE);
84	    }
85	
86	    std::vector<char> buf(block_size);
87	
88	    pcg64 rng(randomSeed());
89	
90	    Stopwatch watch;
91	
92	    std::vector<pollfd> polls(descriptors);
93	
94	    for (size_t i = 0; i < descriptors; ++i)
95	    {
96	        polls[i].fd = fds[i];
97	        polls[i].events = (mode == MODE_READ) ? POLLIN : POLLOUT;
98	        polls[i].revents = 0;
99	    }
100	
101	    size_t ops = 0;
102	    while (ops < count)
103	    {
104	        if (poll(&polls[0], descriptors, -1) <= 0)
105	            throwFromErrno("poll failed", ErrorCodes::SYSTEM_ERROR);
106	        for (size_t i = 0; i < descriptors; ++i)
107	        {
108	            if (!polls[i].revents)
109	                continue;
110	
111	            if (polls[i].revents != polls[i].events)
112	                throw Poco::Exception("revents indicates error");
113	            polls[i].revents = 0;
114	            ++ops;
115	
116	            uint64_t rand_result1 = rng();
117	            uint64_t rand_result2 = rng();
118	            uint64_t rand_result3 = rng();
119	
120	            size_t rand_result = rand_result1 ^ (rand_result2 << 22) ^ (rand_result3 << 43);
121	            size_t offset;
122	            offset = min_offset + rand_result % ((max_offset - min_offset) / block_size) * block_size;
123	
124	            if (mode == MODE_READ)
125	            {
126	                if (static_cast<int>(block_size) != pread(fds[i], &buf[0], block_size, offset))
127	                    throwFromErrno("Cannot read", ErrorCodes::CANNOT_READ_FROM_FILE_DESCRIPTOR);
128	            }
129	            else
130	            {
131	                if (static_cast<int>(block_size) != pwrite(fds[i], &buf[0], block_size, offset))
132	                    throwFromErrno("Cannot write", ErrorCodes::CANNOT_WRITE_TO_FILE_DESCRIPTOR);
133	            }
134	        }
135	    }
136	
137	    for (size_t i = 0; i < descriptors; ++i)
138	    {
139	#if defined(OS_DARWIN)
140	        if (fsync(fds[i]))
141	            throwFromErrno("Cannot fsync", ErrorCodes::CANNOT_FSYNC);
142	#else
143	        if (fdatasync(fds[i]))
144	            throwFromErrno("Cannot fdatasync", ErrorCodes::CANNOT_FSYNC);
145	#endif
146	    }
147	
148	    watch.stop();
149	
150	    for (size_t i = 0; i < descriptors; ++i)
151	    {
152	        if (0 != close(fds[i]))
153	            throwFromErrno("Cannot close file", ErrorCodes::CANNOT_CLOSE_FILE);
154	    }
155	
156	    std::cout << std::fixed << std::setprecision(2)
157	    << "Done " << count  << " ops" << " in " << watch.elapsedSeconds() << " sec."
158	    << ", " << count / watch.elapsedSeconds() << " ops/sec."
159	    << ", " << count * block_size / watch.elapsedSeconds() / 1000000 << " MB/sec."
160	    << std::endl;
161	
162	    return 0;
163	}
